#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<vector<int>> g(n, vector<int>(m));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            cin >> g[i][j];
        }
    }

    // Pattern 0: (i + j) % 2 == 0 is ODD (1), (i + j) % 2 == 1 is EVEN (0)
    // Pattern 1: (i + j) % 2 == 0 is EVEN (0), (i + j) % 2 == 1 is ODD (1)
    int cost0 = 0;
    int cost1 = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            int current_parity = g[i][j] % 2;
            int desired_parity0 = ((i + j) % 2 == 0) ? 1 : 0;
            int desired_parity1 = ((i + j) % 2 == 0) ? 0 : 1;

            if (current_parity != desired_parity0) {
                cost0++;
            }
            if (current_parity != desired_parity1) {
                cost1++;
            }
        }
    }

    int best_pattern = (cost0 <= cost1) ? 0 : 1;
    int min_cost = min(cost0, cost1);

    cout << min_cost << "\n";

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            int desired_parity;
            if (best_pattern == 0) {
                desired_parity = ((i + j) % 2 == 0) ? 1 : 0;
            } else {
                desired_parity = ((i + j) % 2 == 0) ? 0 : 1;
            }

            int val = g[i][j];
            if (val % 2 != desired_parity) {
                val++;
            }
            cout << val << (j == m - 1 ? "" : " ");
        }
        cout << "\n";
    }

    return 0;
}
